"""Independent GUI evidence adapters: generated bytes only, no app or models."""
import json
from types import SimpleNamespace

import pytest

from gnb_player import recognition_drafts as drafts
from gnb_player import recovery_evidence as recovery
from gnb_player.lyrics import fingerprint


@pytest.fixture
def recovery_files(tmp_path):
    source = tmp_path / 'selected recording.mp3'
    source.write_bytes(b'generated exact recording identity, no playable media')
    sha = fingerprint(source)
    cache = tmp_path / 'private station' / 'lyrics-cache'
    failures = cache / 'failures'
    failures.mkdir(parents=True)
    canonical = cache / 'lyrics' / (sha + '.json')
    canonical.parent.mkdir()
    canonical.write_bytes(b'Preserved canonical human lyric content and revision')
    counter = 0

    def failure(text='Original automatic words', **changes):
        nonlocal counter
        counter += 1
        path = failures / (sha + '-' + format(counter, '032x') + '.json')
        payload = {'version': 'extraction-failure-1', 'status': 'failed',
                   'source_sha256': sha, 'created_at': 1, 'message': 'Synthetic timing rejection',
                   'recognition_evidence': {'pre_alignment': [{'text': text}]}}
        payload.update(changes)
        path.write_text(json.dumps(payload, ensure_ascii=False), encoding='utf-8')
        return path

    original = failure()
    snapshot = drafts.create_initial_draft(cache, sha, 'Original automatic words', original)
    return SimpleNamespace(source=source, sha=sha, cache=cache, canonical=canonical,
                           original=original, snapshot=snapshot, failure=failure)


def artifact_bytes(files):
    """Ignore lock metadata; compare content that this read adapter must retain."""
    return {str(path.relative_to(files.cache)): path.read_bytes()
            for path in files.cache.rglob('*') if path.is_file() and path.suffix == '.json'}


def test_reopen_without_worker_event_keeps_human_text_and_original_provenance(recovery_files):
    files = recovery_files
    edited = drafts.save_user_draft(files.snapshot.path, 'Human correction — 雨\nNext line',
                                   expected_revision=files.snapshot.revision,
                                   expected_source_sha256=files.sha)
    before = artifact_bytes(files)
    source_before = files.source.read_bytes()
    opened = recovery.load_open_data(files.cache, files.source)
    assert opened.snapshot.raw_payload == edited.raw_payload
    assert opened.original_text == 'Original automatic words'
    assert opened.source_sha256 == files.sha
    assert opened.source_stamp == recovery.source_stamp(files.source)
    assert 'Original failure report (unchanged)' in opened.diagnostics_text
    assert 'Original automatic words' in opened.diagnostics_text
    assert 'Human correction' not in opened.diagnostics_text
    assert opened.snapshot.payload['status'] == 'unaligned'
    assert opened.snapshot.payload['needs_review'] is True
    assert not {'segments', 'human_review', 'approved', 'publication'} & opened.snapshot.payload.keys()
    assert artifact_bytes(files) == before and files.source.read_bytes() == source_before


def test_latest_failure_is_separate_from_original_and_saved_human_text(recovery_files):
    files = recovery_files
    edited = drafts.save_user_draft(files.snapshot.path, 'Keep this human revision',
                                   expected_revision=files.snapshot.revision,
                                   expected_source_sha256=files.sha)
    latest = files.failure('Different retry machine guess')
    before = artifact_bytes(files)
    event = {'source_sha256': files.sha, 'diagnostic_path': str(latest),
             'recognition_draft_path': str(files.snapshot.path)}
    opened = recovery.load_open_data(files.cache, files.source, event)
    assert opened.snapshot.raw_payload == edited.raw_payload
    assert opened.original_text == 'Original automatic words'
    assert 'Original failure report (unchanged)' in opened.diagnostics_text
    assert 'Latest failure report (unchanged)' in opened.diagnostics_text
    assert 'Different retry machine guess' in opened.diagnostics_text
    assert artifact_bytes(files) == before


def test_raw_only_report_can_open_without_creating_a_draft(recovery_files):
    files = recovery_files
    files.snapshot.path.unlink()
    before = artifact_bytes(files)
    opened = recovery.load_open_data(files.cache, files.source,
                                    {'source_sha256': files.sha, 'diagnostic_path': str(files.original)})
    assert opened.snapshot is None
    assert opened.original_text == 'Original automatic words'
    assert files.original.read_text() in opened.diagnostics_text
    assert not files.snapshot.path.exists() and artifact_bytes(files) == before


def test_corrupt_untimed_file_falls_back_to_immutable_raw_report_without_replacing_it(recovery_files):
    files = recovery_files
    files.snapshot.path.write_bytes(b'Unknown preserved human file, not a supported draft')
    before = artifact_bytes(files)
    opened = recovery.load_open_data(files.cache, files.source,
                                    {'source_sha256': files.sha, 'diagnostic_path': str(files.original)})
    assert opened.snapshot is None and opened.draft_error
    assert 'Editable draft was not opened' in opened.diagnostics_text
    assert opened.original_text == 'Original automatic words'
    assert artifact_bytes(files) == before


def test_wrong_recording_event_never_opens_a_valid_other_recording_draft(recovery_files):
    files = recovery_files
    before = artifact_bytes(files)
    with pytest.raises(recovery.RecoveryOpenError, match='earlier recording bytes'):
        recovery.load_open_data(files.cache, files.source,
                                {'source_sha256': '0' * 64, 'recognition_draft_path': str(files.snapshot.path)})
    assert artifact_bytes(files) == before


@pytest.mark.parametrize('field', ['recognition_draft_path', 'diagnostic_path'])
def test_worker_parent_traversal_paths_are_refused_even_if_they_resolve_inside_cache(recovery_files, field):
    files = recovery_files
    target = files.snapshot.path if field == 'recognition_draft_path' else files.original
    traversal = target.parent / '..' / target.parent.name / target.name
    before = artifact_bytes(files)
    with pytest.raises(recovery.RecoveryOpenError, match='parent directories'):
        recovery.load_open_data(files.cache, files.source,
                                {'source_sha256': files.sha, field: str(traversal)})
    assert artifact_bytes(files) == before


@pytest.mark.parametrize('field', ['recognition_draft_path', 'diagnostic_path'])
def test_worker_outside_cache_paths_are_refused_without_reading_them(recovery_files, tmp_path, field):
    files = recovery_files
    outside = tmp_path / 'external preserved file.json'
    outside.write_text('This unrelated document must not become recovery text.')
    before = artifact_bytes(files)
    with pytest.raises(recovery.RecoveryOpenError, match='outside'):
        recovery.load_open_data(files.cache, files.source,
                                {'source_sha256': files.sha, field: str(outside)})
    assert artifact_bytes(files) == before
    assert outside.read_text() == 'This unrelated document must not become recovery text.'


def test_original_failure_digest_mismatch_keeps_all_files(recovery_files):
    files = recovery_files
    payload = json.loads(files.original.read_text())
    payload['message'] = 'Externally replaced original failure message'
    files.original.write_text(json.dumps(payload))
    before = artifact_bytes(files)
    with pytest.raises(recovery.RecoveryOpenError, match='original failure report changed'):
        recovery.load_open_data(files.cache, files.source)
    assert artifact_bytes(files) == before


def test_symlinked_failure_is_never_followed(recovery_files, tmp_path):
    files = recovery_files
    outside = tmp_path / 'external-original.json'
    outside.write_bytes(files.original.read_bytes())
    files.original.unlink()
    files.original.symlink_to(outside)
    before = outside.read_bytes()
    with pytest.raises((ValueError, OSError)):
        recovery.load_open_data(files.cache, files.source)
    assert files.original.is_symlink() and outside.read_bytes() == before
    assert files.canonical.read_bytes() == b'Preserved canonical human lyric content and revision'


def test_symlinked_draft_can_only_show_valid_raw_diagnostics(recovery_files, tmp_path):
    files = recovery_files
    outside = tmp_path / 'external-draft.json'
    outside.write_bytes(files.snapshot.raw_payload)
    files.snapshot.path.unlink()
    files.snapshot.path.symlink_to(outside)
    before = outside.read_bytes()
    opened = recovery.load_open_data(files.cache, files.source,
                                    {'source_sha256': files.sha, 'diagnostic_path': str(files.original)})
    assert opened.snapshot is None and opened.draft_error
    assert files.snapshot.path.is_symlink() and outside.read_bytes() == before


@pytest.mark.parametrize('payload', [b'broken JSON', b'{"version":"other"}',
                                  b'{"source_sha256":"duplicate","source_sha256":"duplicate"}'])
def test_malformed_raw_report_is_refused_without_any_partial_draft_creation(recovery_files, payload):
    files = recovery_files
    files.snapshot.path.unlink()
    files.original.write_bytes(payload)
    before = artifact_bytes(files)
    with pytest.raises(ValueError):
        recovery.load_open_data(files.cache, files.source,
                                {'source_sha256': files.sha, 'diagnostic_path': str(files.original)})
    assert artifact_bytes(files) == before and not files.snapshot.path.exists()


def test_recording_change_during_draft_read_is_rejected(recovery_files, monkeypatch):
    files = recovery_files
    before = artifact_bytes(files)
    real_load = recovery.load_draft
    def replace_recording(*args, **kwargs):
        result = real_load(*args, **kwargs)
        files.source.write_bytes(b'Later bytes at the same recording path')
        return result
    monkeypatch.setattr(recovery, 'load_draft', replace_recording)
    with pytest.raises(recovery.RecoveryOpenError, match='recording changed'):
        recovery.load_open_data(files.cache, files.source)
    assert artifact_bytes(files) == before


def test_recording_change_after_final_hash_cannot_be_blessed_with_a_new_stamp(recovery_files, monkeypatch):
    """A completion stamp must belong to the bytes actually fingerprinted."""
    files = recovery_files
    before = artifact_bytes(files)
    real_hash = recovery.fingerprint
    calls = 0
    def replace_after_read(path):
        nonlocal calls
        calls += 1
        result = real_hash(path)
        if calls == 2:
            files.source.write_bytes(b'Replacement made after the final hash read')
        return result
    monkeypatch.setattr(recovery, 'fingerprint', replace_after_read)
    with pytest.raises(recovery.RecoveryOpenError, match='recording changed'):
        recovery.load_open_data(files.cache, files.source)
    assert calls == 2 and artifact_bytes(files) == before
